-- =====================================================================
--  أثر لتصميم الويب — Athar Web Design (Qatar)
--  MySQL 8.0+ / MariaDB 10.4+ schema
--
--  Conventions
--    * ids are UUID v4 strings (CHAR(36)) generated by the PHP layer
--    * bilingual fields and lists are JSON columns; every JSON column carries
--      COMMENT 'json' so the PHP driver decodes it on MariaDB too, where the
--      JSON type is an alias of LONGTEXT
--    * timestamps are stored in UTC (the driver sets the session time_zone)
--    * safe to re-run: every statement uses IF NOT EXISTS
-- =====================================================================

SET NAMES utf8mb4;
SET time_zone = '+00:00';

-- ---------- admin users ----------
CREATE TABLE IF NOT EXISTS admin_users (
  id            CHAR(36)     NOT NULL,
  name          VARCHAR(120) NOT NULL,
  email         VARCHAR(191) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  role          VARCHAR(20)  NOT NULL DEFAULT 'admin',
  lang          VARCHAR(5)   NOT NULL DEFAULT 'en',
  is_active     TINYINT(1)   NOT NULL DEFAULT 1,
  last_login_at DATETIME     NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_admin_users_email (email),
  CONSTRAINT chk_admin_users_role CHECK (role IN ('owner','admin','editor')),
  CONSTRAINT chk_admin_users_lang CHECK (lang IN ('ar','en'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS login_attempts (
  id         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  email      VARCHAR(191) NULL,
  ip         VARCHAR(64)  NULL,
  success    TINYINT(1)   NOT NULL DEFAULT 0,
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_login_attempts_ip (ip, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- ---------- settings (key / value) ----------
CREATE TABLE IF NOT EXISTS settings (
  `key`      VARCHAR(100) NOT NULL,
  value      JSON         NULL COMMENT 'json',
  `group`    VARCHAR(40)  NOT NULL DEFAULT 'general',
  updated_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- ---------- pages (block based, bilingual) ----------
CREATE TABLE IF NOT EXISTS pages (
  id               CHAR(36)     NOT NULL,
  slug             VARCHAR(191) NOT NULL,
  template         VARCHAR(40)  NOT NULL DEFAULT 'custom',
  title            JSON         NULL COMMENT 'json',
  nav_label        JSON         NULL COMMENT 'json',
  meta_title       JSON         NULL COMMENT 'json',
  meta_description JSON         NULL COMMENT 'json',
  meta_keywords    JSON         NULL COMMENT 'json',
  og_image         VARCHAR(500) NULL,
  canonical_url    VARCHAR(500) NULL,
  noindex          TINYINT(1)   NOT NULL DEFAULT 0,
  blocks           JSON         NULL COMMENT 'json',
  status           VARCHAR(20)  NOT NULL DEFAULT 'published',
  show_in_nav      TINYINT(1)   NOT NULL DEFAULT 1,
  show_in_footer   TINYINT(1)   NOT NULL DEFAULT 0,
  nav_order        INT          NOT NULL DEFAULT 100,
  is_system        TINYINT(1)   NOT NULL DEFAULT 0,
  created_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_pages_slug (slug),
  KEY idx_pages_nav (status, show_in_nav, nav_order),
  CONSTRAINT chk_pages_status CHECK (status IN ('draft','published'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- ---------- services ----------
CREATE TABLE IF NOT EXISTS services (
  id               CHAR(36)     NOT NULL,
  slug             VARCHAR(191) NOT NULL,
  title            JSON         NULL COMMENT 'json',
  excerpt          JSON         NULL COMMENT 'json',
  body             JSON         NULL COMMENT 'json',
  icon             VARCHAR(80)  NULL,
  image            VARCHAR(500) NULL,
  features         JSON         NULL COMMENT 'json',
  meta_title       JSON         NULL COMMENT 'json',
  meta_description JSON         NULL COMMENT 'json',
  meta_keywords    JSON         NULL COMMENT 'json',
  sort_order       INT          NOT NULL DEFAULT 100,
  is_featured      TINYINT(1)   NOT NULL DEFAULT 1,
  status           VARCHAR(20)  NOT NULL DEFAULT 'published',
  created_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_services_slug (slug),
  KEY idx_services_list (status, sort_order),
  CONSTRAINT chk_services_status CHECK (status IN ('draft','published'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- ---------- portfolio ----------
CREATE TABLE IF NOT EXISTS project_categories (
  id         CHAR(36)     NOT NULL,
  slug       VARCHAR(191) NOT NULL,
  name       JSON         NULL COMMENT 'json',
  sort_order INT          NOT NULL DEFAULT 100,
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_project_categories_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS projects (
  id               CHAR(36)      NOT NULL,
  slug             VARCHAR(191)  NOT NULL,
  title            JSON          NULL COMMENT 'json',
  client           VARCHAR(191)  NULL,
  category_id      CHAR(36)      NULL,
  excerpt          JSON          NULL COMMENT 'json',
  body             JSON          NULL COMMENT 'json',
  cover_image      VARCHAR(500)  NULL,
  gallery          JSON          NULL COMMENT 'json',
  services         JSON          NULL COMMENT 'json',
  results          JSON          NULL COMMENT 'json',
  link             VARCHAR(500)  NULL,
  year             INT           NULL,
  is_featured      TINYINT(1)    NOT NULL DEFAULT 0,
  sort_order       INT           NOT NULL DEFAULT 100,
  status           VARCHAR(20)   NOT NULL DEFAULT 'published',
  meta_title       JSON          NULL COMMENT 'json',
  meta_description JSON          NULL COMMENT 'json',
  meta_keywords    JSON          NULL COMMENT 'json',
  created_at       DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_projects_slug (slug),
  KEY idx_projects_cat (category_id),
  KEY idx_projects_list (status, sort_order),
  CONSTRAINT fk_projects_category FOREIGN KEY (category_id) REFERENCES project_categories (id) ON DELETE SET NULL,
  CONSTRAINT chk_projects_status CHECK (status IN ('draft','published'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- ---------- testimonials ----------
CREATE TABLE IF NOT EXISTS testimonials (
  id          CHAR(36)     NOT NULL,
  author_name VARCHAR(191) NOT NULL,
  author_role JSON         NULL COMMENT 'json',
  company     VARCHAR(191) NULL,
  quote       JSON         NULL COMMENT 'json',
  avatar      VARCHAR(500) NULL,
  rating      TINYINT      NOT NULL DEFAULT 5,
  sort_order  INT          NOT NULL DEFAULT 100,
  status      VARCHAR(20)  NOT NULL DEFAULT 'published',
  created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT chk_testimonials_rating CHECK (rating BETWEEN 1 AND 5),
  CONSTRAINT chk_testimonials_status CHECK (status IN ('draft','published'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- ---------- media library ----------
CREATE TABLE IF NOT EXISTS media (
  id         CHAR(36)     NOT NULL,
  filename   VARCHAR(255) NOT NULL,
  path       VARCHAR(500) NOT NULL,
  url        VARCHAR(500) NOT NULL,
  mime       VARCHAR(100) NULL,
  size       INT          NULL,
  width      INT          NULL,
  height     INT          NULL,
  alt        JSON         NULL COMMENT 'json',
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_media_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- ---------- leads (contact form) ----------
CREATE TABLE IF NOT EXISTS leads (
  id         CHAR(36)     NOT NULL,
  name       VARCHAR(191) NOT NULL,
  phone      VARCHAR(60)  NULL,
  email      VARCHAR(191) NULL,
  company    VARCHAR(191) NULL,
  service    VARCHAR(191) NULL,
  message    TEXT         NULL,
  source     VARCHAR(40)  NOT NULL DEFAULT 'form',
  page       VARCHAR(300) NULL,
  lang       VARCHAR(5)   NULL,
  status     VARCHAR(20)  NOT NULL DEFAULT 'new',
  notes      TEXT         NULL,
  ip         VARCHAR(64)  NULL,
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_leads_created (created_at),
  KEY idx_leads_status (status, created_at),
  KEY idx_leads_ip (ip, created_at),
  CONSTRAINT chk_leads_status CHECK (status IN ('new','contacted','won','lost'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- ---------- analytics ----------
CREATE TABLE IF NOT EXISTS visitors (
  id           CHAR(36)     NOT NULL,
  first_seen   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_seen    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  visits_count INT          NOT NULL DEFAULT 1,
  country      VARCHAR(80)  NULL,
  country_code VARCHAR(2)   NULL,
  city         VARCHAR(80)  NULL,
  ip           VARCHAR(64)  NULL,
  user_agent   VARCHAR(500) NULL,
  device       VARCHAR(20)  NULL,
  browser      VARCHAR(40)  NULL,
  os           VARCHAR(40)  NULL,
  referrer     VARCHAR(500) NULL,
  landing_page VARCHAR(300) NULL,
  lang         VARCHAR(5)   NULL,
  is_bot       TINYINT(1)   NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY idx_visitors_last_seen (last_seen),
  KEY idx_visitors_ip (ip)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS visits (
  id           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visitor_id   CHAR(36)     NOT NULL,
  session_id   CHAR(36)     NOT NULL,
  path         VARCHAR(300) NOT NULL,
  lang         VARCHAR(5)   NULL,
  title        VARCHAR(200) NULL,
  referrer     VARCHAR(500) NULL,
  utm_source   VARCHAR(100) NULL,
  utm_medium   VARCHAR(100) NULL,
  utm_campaign VARCHAR(100) NULL,
  ip           VARCHAR(64)  NULL,
  country      VARCHAR(80)  NULL,
  country_code VARCHAR(2)   NULL,
  city         VARCHAR(80)  NULL,
  device       VARCHAR(20)  NULL,
  browser      VARCHAR(40)  NULL,
  os           VARCHAR(40)  NULL,
  user_agent   VARCHAR(500) NULL,
  is_bot       TINYINT(1)   NOT NULL DEFAULT 0,
  created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_visits_created (created_at),
  KEY idx_visits_visitor (visitor_id, created_at),
  KEY idx_visits_ip (ip, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS clicks (
  id           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visitor_id   CHAR(36)     NULL,
  session_id   CHAR(36)     NULL,
  event        VARCHAR(40)  NOT NULL,
  target       VARCHAR(500) NULL,
  label        VARCHAR(120) NULL,
  path         VARCHAR(300) NULL,
  lang         VARCHAR(5)   NULL,
  ip           VARCHAR(64)  NULL,
  country      VARCHAR(80)  NULL,
  country_code VARCHAR(2)   NULL,
  device       VARCHAR(20)  NULL,
  is_bot       TINYINT(1)   NOT NULL DEFAULT 0,
  created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_clicks_created (created_at),
  KEY idx_clicks_visitor (visitor_id, created_at),
  KEY idx_clicks_event (event, created_at),
  KEY idx_clicks_ip (ip, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS geo_cache (
  ip           VARCHAR(64) NOT NULL,
  country      VARCHAR(80) NULL,
  country_code VARCHAR(2)  NULL,
  city         VARCHAR(80) NULL,
  created_at   DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (ip)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- ---------- SEO ----------
CREATE TABLE IF NOT EXISTS seo_tasks (
  id           CHAR(36)     NOT NULL,
  title        VARCHAR(255) NOT NULL,
  description  TEXT         NULL,
  page_slug    VARCHAR(191) NULL,
  url          VARCHAR(500) NULL,
  category     VARCHAR(20)  NOT NULL DEFAULT 'onpage',
  priority     VARCHAR(10)  NOT NULL DEFAULT 'medium',
  status       VARCHAR(20)  NOT NULL DEFAULT 'todo',
  due_date     DATE         NULL,
  completed_at DATETIME     NULL,
  checklist    JSON         NULL COMMENT 'json',
  notes        TEXT         NULL,
  sort_order   INT          NOT NULL DEFAULT 100,
  created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_seo_tasks_status (status, sort_order),
  CONSTRAINT chk_seo_tasks_category CHECK (category IN ('technical','content','onpage','offpage','local','social','performance')),
  CONSTRAINT chk_seo_tasks_priority CHECK (priority IN ('low','medium','high')),
  CONSTRAINT chk_seo_tasks_status CHECK (status IN ('todo','in_progress','review','done'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS redirects (
  id         CHAR(36)     NOT NULL,
  from_path  VARCHAR(500) NOT NULL,
  to_path    VARCHAR(500) NOT NULL,
  code       SMALLINT     NOT NULL DEFAULT 301,
  hits       INT          NOT NULL DEFAULT 0,
  is_active  TINYINT(1)   NOT NULL DEFAULT 1,
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_redirects_from (from_path(191)),
  CONSTRAINT chk_redirects_code CHECK (code IN (301,302))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- ---------- activity log ----------
CREATE TABLE IF NOT EXISTS activity_log (
  id         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id    CHAR(36)     NULL,
  user_name  VARCHAR(120) NULL,
  action     VARCHAR(60)  NOT NULL,
  entity     VARCHAR(60)  NULL,
  entity_id  VARCHAR(64)  NULL,
  details    JSON         NULL COMMENT 'json',
  ip         VARCHAR(64)  NULL,
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_activity_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- ---------- service packages ----------
CREATE TABLE IF NOT EXISTS packages (
  id               CHAR(36)      NOT NULL,
  slug             VARCHAR(191)  NOT NULL,
  category         VARCHAR(20)   NOT NULL DEFAULT 'website',
  tier             VARCHAR(20)   NOT NULL DEFAULT 'silver',
  name             JSON          NULL COMMENT 'json',
  tagline          JSON          NULL COMMENT 'json',
  body             JSON          NULL COMMENT 'json',
  price            DECIMAL(12,2) NULL,
  currency         VARCHAR(8)    NOT NULL DEFAULT 'QAR',
  price_prefix     JSON          NULL COMMENT 'json',
  period           JSON          NULL COMMENT 'json',
  price_note       JSON          NULL COMMENT 'json',
  delivery         JSON          NULL COMMENT 'json',
  features         JSON          NULL COMMENT 'json',
  whatsapp_message JSON          NULL COMMENT 'json',
  cta_text         JSON          NULL COMMENT 'json',
  badge            JSON          NULL COMMENT 'json',
  is_highlighted   TINYINT(1)    NOT NULL DEFAULT 0,
  image            VARCHAR(500)  NULL,
  meta_title       JSON          NULL COMMENT 'json',
  meta_description JSON          NULL COMMENT 'json',
  meta_keywords    JSON          NULL COMMENT 'json',
  sort_order       INT           NOT NULL DEFAULT 100,
  status           VARCHAR(20)   NOT NULL DEFAULT 'published',
  created_at       DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_packages_slug (slug),
  KEY idx_packages_category (category, tier, sort_order),
  CONSTRAINT chk_packages_category CHECK (category IN ('bundle','website','social','seo','photography')),
  CONSTRAINT chk_packages_tier CHECK (tier IN ('silver','elite','premium')),
  CONSTRAINT chk_packages_status CHECK (status IN ('draft','published'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- =====================================================================
--  Email marketing
-- =====================================================================
CREATE TABLE IF NOT EXISTS mail_senders (
  id               CHAR(36)     NOT NULL,
  name             VARCHAR(120) NOT NULL,
  email            VARCHAR(191) NOT NULL,
  reply_to         VARCHAR(191) NULL,
  smtp_host        VARCHAR(191) NOT NULL,
  smtp_port        INT          NOT NULL DEFAULT 587,
  smtp_user        VARCHAR(191) NULL,
  smtp_pass        VARCHAR(255) NULL,
  smtp_secure      VARCHAR(5)   NOT NULL DEFAULT 'tls',
  hourly_limit     INT          NOT NULL DEFAULT 100,
  daily_limit      INT          NOT NULL DEFAULT 500,
  dkim_selector    VARCHAR(64)  NULL,
  dkim_private_key TEXT         NULL,
  is_active        TINYINT(1)   NOT NULL DEFAULT 1,
  last_test_at     DATETIME     NULL,
  last_test_ok     TINYINT(1)   NULL,
  dns_check        JSON         NULL COMMENT 'json',
  sent_today       INT          NOT NULL DEFAULT 0,
  sent_today_date  DATE         NULL,
  sort_order       INT          NOT NULL DEFAULT 100,
  created_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT chk_mail_senders_secure CHECK (smtp_secure IN ('tls','ssl','none'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS mail_lists (
  id             CHAR(36)     NOT NULL,
  name           VARCHAR(120) NOT NULL,
  description    VARCHAR(500) NULL,
  contacts_count INT          NOT NULL DEFAULT 0,
  created_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS mail_contacts (
  id              CHAR(36)     NOT NULL,
  list_id         CHAR(36)     NOT NULL,
  email           VARCHAR(191) NOT NULL,
  name            VARCHAR(191) NULL,
  company         VARCHAR(191) NULL,
  status          VARCHAR(20)  NOT NULL DEFAULT 'pending',
  score           INT          NULL,
  checks          JSON         NULL COMMENT 'json',
  verified_at     DATETIME     NULL,
  unsubscribed_at DATETIME     NULL,
  created_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_mail_contacts_list_email (list_id, email),
  KEY idx_mail_contacts_list (list_id, status),
  KEY idx_mail_contacts_email (email),
  CONSTRAINT fk_mail_contacts_list FOREIGN KEY (list_id) REFERENCES mail_lists (id) ON DELETE CASCADE,
  CONSTRAINT chk_mail_contacts_status CHECK (status IN ('pending','valid','risky','invalid','unsubscribed','bounced'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS mail_templates (
  id         CHAR(36)     NOT NULL,
  name       VARCHAR(120) NOT NULL,
  subject    VARCHAR(255) NULL,
  html       MEDIUMTEXT   NOT NULL,
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS mail_campaigns (
  id                CHAR(36)     NOT NULL,
  name              VARCHAR(160) NOT NULL,
  subject           VARCHAR(255) NOT NULL DEFAULT '',
  preheader         VARCHAR(255) NULL,
  sender_ids        JSON         NULL COMMENT 'json',
  list_ids          JSON         NULL COMMENT 'json',
  template_id       CHAR(36)     NULL,
  html              MEDIUMTEXT   NOT NULL,
  status            VARCHAR(20)  NOT NULL DEFAULT 'draft',
  scheduled_at      DATETIME     NULL,
  started_at        DATETIME     NULL,
  finished_at       DATETIME     NULL,
  throttle_per_hour INT          NOT NULL DEFAULT 200,
  skip_risky        TINYINT(1)   NOT NULL DEFAULT 1,
  score             JSON         NULL COMMENT 'json',
  stats             JSON         NULL COMMENT 'json',
  created_at        DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at        DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_mail_campaigns_status (status, scheduled_at),
  CONSTRAINT fk_mail_campaigns_template FOREIGN KEY (template_id) REFERENCES mail_templates (id) ON DELETE SET NULL,
  CONSTRAINT chk_mail_campaigns_status CHECK (status IN ('draft','scheduled','sending','paused','sent','cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS mail_queue (
  id          CHAR(36)     NOT NULL,
  campaign_id CHAR(36)     NOT NULL,
  contact_id  CHAR(36)     NULL,
  sender_id   CHAR(36)     NULL,
  email       VARCHAR(191) NOT NULL,
  name        VARCHAR(191) NULL,
  token       VARCHAR(64)  NOT NULL,
  status      VARCHAR(20)  NOT NULL DEFAULT 'queued',
  attempts    INT          NOT NULL DEFAULT 0,
  error       VARCHAR(300) NULL,
  sent_at     DATETIME     NULL,
  opened_at   DATETIME     NULL,
  clicked_at  DATETIME     NULL,
  created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_mail_queue_token (token),
  KEY idx_mail_queue_campaign (campaign_id, status),
  KEY idx_mail_queue_sender (sender_id, sent_at),
  CONSTRAINT fk_mail_queue_campaign FOREIGN KEY (campaign_id) REFERENCES mail_campaigns (id) ON DELETE CASCADE,
  CONSTRAINT fk_mail_queue_contact FOREIGN KEY (contact_id) REFERENCES mail_contacts (id) ON DELETE SET NULL,
  CONSTRAINT fk_mail_queue_sender FOREIGN KEY (sender_id) REFERENCES mail_senders (id) ON DELETE SET NULL,
  CONSTRAINT chk_mail_queue_status CHECK (status IN ('queued','sent','failed','skipped'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS mail_events (
  id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  campaign_id CHAR(36)     NOT NULL,
  queue_id    CHAR(36)     NULL,
  event       VARCHAR(20)  NOT NULL,
  url         VARCHAR(500) NULL,
  ip          VARCHAR(64)  NULL,
  user_agent  VARCHAR(300) NULL,
  created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_mail_events_campaign (campaign_id, event),
  CONSTRAINT chk_mail_events_event CHECK (event IN ('open','click','unsubscribe','bounce','complaint'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS mail_suppressions (
  email      VARCHAR(191) NOT NULL,
  reason     VARCHAR(20)  NOT NULL DEFAULT 'unsubscribe',
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
